-- An `ON UPDATE SET NULL` fires once the statement's rows are written, so a later target
-- row's CHECK outranks the oversized entry the nulled child would enter into a partial index.
-- @setup
CREATE TABLE p (k text PRIMARY KEY, v int CHECK (v > 0));
CREATE TABLE c (pad text, k text REFERENCES p ON UPDATE SET NULL);
CREATE INDEX c_pi ON c (pad) WHERE k IS NULL;
INSERT INTO p VALUES ('a', 1), ('b', 1);
INSERT INTO c VALUES ('', 'a');
-- @test
-- @expect-error: the second row fails its CHECK before the SET NULL runs
-- @expect-message
-- @profile-lock
UPDATE p SET k = CASE WHEN k = 'a' THEN 'az' ELSE k END, v = CASE WHEN k = 'b' THEN -1 ELSE v END;
